def norm(s: str) -> str:
    return " ".join(re.findall(r"\w+", s.casefold()))


def sha(s: str) -> str:
    return hashlib.sha256(s.encode("utf-8")).hexdigest()


def main() -> None:
    conn = sqlite3.connect(DB)
    existing = {norm(row[0]) for row in conn.execute("SELECT complaint_text FROM scenario")}
    rows = []
    for pid, text in EXAMPLES.items():
        row = conn.execute("SELECT legal_status,provision_kind,verified_text,source_pdf_page "
                           "FROM provision WHERE provision_id=?", (pid,)).fetchone()
        if not row or row[0] != "in_force" or row[1] != "offence" or not row[2] or not row[3]:
            raise ValueError(f"Source/status not ready: {pid}")
        if norm(text) in existing: raise ValueError(f"Already present: {pid}")
        existing.add(norm(text))
        target = {"outcome": "provision_match", "possible_provision_ids": [pid],
                  "uncertain_sections": []}
        rows.append({"id": f"section-floor-{pid}",
                     "messages": [{"role": "system", "content": SYSTEM},
                                  {"role": "user", "content": text},
                                  {"role": "assistant", "content": json.dumps(target, separators=(",", ":"))}],
                     "metadata": {"kind": "triage", "split": "train", "target_provision_id": pid,
                                  "source_pdf_page": row[3],
                                  "verified_text_sha256": sha(row[2]),
                                  "review_status": "single_AI_authored_source_grounded_research_case",
                                  "quality_limit": "One example does not demonstrate section-level reliability."}})
    conn.close()
    OUT.mkdir(parents=True, exist_ok=True)
    with (OUT / "train.jsonl").open("w", encoding="utf-8", newline="\n") as stream:
        for row in rows: stream.write(json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n")
    report = {"positive_train_examples": len(rows), "non_standalone": NON_STANDALONE,
              "coverage_limit": "Research only; no dev or sealed cases for these sections yet.",
              "train_sha256": hashlib.sha256((OUT / "train.jsonl").read_bytes()).hexdigest()}
    (OUT / "manifest.json").write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(report, indent=2))


if __name__ == "__main__": main()
